/* ============================================================================
   UTILITIES
   ============================================================================ */

function titleCaseWord(s) {
  if (!s) return s;
  return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
}

// Italian prepositions/articles that stay lowercase mid-name (never as the first word)
const IT_LOWERCASE_WORDS = new Set(['al', 'ai', 'allo', 'agli', 'alla', 'alle', 'di', 'del', 'dei', 'dello', 'degli', 'della', 'delle', 'da', 'dal', 'dai', 'dallo', 'dagli', 'dalla', 'dalle', 'in', 'nel', 'nei', 'della', 'su', 'sul', 'sui', 'sullo', 'sugli', 'sulla', 'sulle', 'e', 'ed', 'la', 'le', 'lo', 'gli', 'il']);

// Excel PROPER()-equivalent: capitalize first letter of each word, but keep
// Italian prepositions/articles lowercase when they're not the first word
// (e.g. "Montorio al Vomano", not "Montorio Al Vomano").
function properCase(s) {
  if (!s) return s;
  const parts = s.split(/(\s+|-)/);
  let firstWordSeen = false;
  return parts.map(part => {
    if (/^[\s-]+$/.test(part) || part === '') return part;
    const isFirst = !firstWordSeen;
    firstWordSeen = true;
    if (!isFirst && IT_LOWERCASE_WORDS.has(part.toLowerCase())) return part.toLowerCase();
    return titleCaseWord(part);
  }).join('');
}

function stripComuneDiPrefix(s) {
  if (!s) return s;
  const proper = properCase(s.trim());
  return proper.replace(/^Comune Di\s*/i, '').trim();
}

function projectIdPrefix2(pid) {
  const parts = (pid || '').split('-');
  return parts.length >= 2 ? `${parts[0]}-${parts[1]}` : pid;
}

function projectIdSegments(pid) {
  const parts = (pid || '').split('-');
  return { first: parts[0], second: parts[1] };
}

function fmtEUR(n) {
  if (n === null || n === undefined) return '—';
  if (typeof n !== 'number') return String(n);
  if (isNaN(n)) return '—';
  return n.toLocaleString('it-IT', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Number formatting for CSV export, Italian convention (comma = decimal, dot = thousands).
// Preserves the value's real precision instead of forcing 2 decimals, since these numbers
// get pasted back into formulas/sums where the extra digits matter. Passes non-numbers
// (some columns mix real numbers with the odd text/header value) straight through.
function fmtEURExport(n) {
  if (n === null || n === undefined) return '';
  if (typeof n !== 'number') return String(n);
  if (isNaN(n)) return '';
  return n.toLocaleString('it-IT', { minimumFractionDigits: 0, maximumFractionDigits: 6 });
}

function toCSV(rows, columns) {
  const esc = (v) => {
    if (v === null || v === undefined) return '';
    const s = String(v);
    return /[;"\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const header = columns.map(c => esc(c.label)).join(';');
  const lines = rows.map(r => columns.map(c => esc(c.get(r))).join(';'));
  return [header, ...lines].join('\n');
}

function downloadText(filename, text) {
  const blob = new Blob(['\uFEFF' + text], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

let _keyCounter = 0;
function nextKey() { return `k${_keyCounter++}`; }

/* ============================================================================
   EXCEL PARSING HELPERS

   Two formats arrive here:
     - real .xlsx (DB commesse, SGP report)  -> parsed by SheetJS
     - NetSuite ".xls" exports (BDV, P&L)    -> actually SpreadsheetML 2003 (XLML),
                                                an XML dialect, NOT a binary .xls

   XLML is parsed by our own parser below rather than by SheetJS on purpose.
   Several SheetJS distributions (the "mini"/"lite" builds commonly pulled from
   CDNs) ship without the XLML parser and throw "parse_xlml is not defined" the
   moment one of these files is opened. Parsing it ourselves makes the app behave
   identically no matter which SheetJS build the host page happens to load.
   ============================================================================ */

function isXLML(text) {
  const head = text.slice(0, 1000);
  return head.includes('<?xml') && head.includes('urn:schemas-microsoft-com:office:spreadsheet');
}

// collect direct/descendant elements by local name, namespace-agnostic
function elemsByLocalName(root, localName) {
  const out = [];
  const all = root.getElementsByTagName('*');
  for (let i = 0; i < all.length; i++) {
    const el = all[i];
    const ln = el.localName || (el.nodeName.includes(':') ? el.nodeName.split(':').pop() : el.nodeName);
    if (ln === localName) out.push(el);
  }
  return out;
}

function localNameOf(el) {
  return el.localName || (el.nodeName.includes(':') ? el.nodeName.split(':').pop() : el.nodeName);
}

function childrenByLocalName(el, localName) {
  const out = [];
  for (let i = 0; i < el.childNodes.length; i++) {
    const c = el.childNodes[i];
    if (c.nodeType === 1 && localNameOf(c) === localName) out.push(c);
  }
  return out;
}

// read an ss:-namespaced attribute regardless of prefix
function ssAttr(el, name) {
  return el.getAttribute('ss:' + name) ?? el.getAttribute(name);
}

function parseXLML(text, DOMParserImpl) {
  const parser = new DOMParserImpl();
  const doc = parser.parseFromString(text, 'text/xml');

  const parseError = doc.getElementsByTagName('parsererror');
  if (parseError && parseError.length) {
    throw new Error('Il file XML non è leggibile (documento malformato).');
  }

  const SheetNames = [];
  const rowsBySheet = {};

  const worksheets = elemsByLocalName(doc, 'Worksheet');
  for (const wsEl of worksheets) {
    const name = ssAttr(wsEl, 'Name') || `Sheet${SheetNames.length + 1}`;
    SheetNames.push(name);

    const rows = [];
    const tables = childrenByLocalName(wsEl, 'Table');
    const table = tables[0];
    if (!table) { rowsBySheet[name] = rows; continue; }

    let rowIdx = 0; // 0-based cursor into rows[]
    for (const rowEl of childrenByLocalName(table, 'Row')) {
      const rIndex = ssAttr(rowEl, 'Index');
      if (rIndex) rowIdx = parseInt(rIndex, 10) - 1; // ss:Index is 1-based

      const row = [];
      let colIdx = 0;
      for (const cellEl of childrenByLocalName(rowEl, 'Cell')) {
        const cIndex = ssAttr(cellEl, 'Index');
        if (cIndex) colIdx = parseInt(cIndex, 10) - 1;

        const dataEls = childrenByLocalName(cellEl, 'Data');
        let value = null;
        if (dataEls.length) {
          const d = dataEls[0];
          const type = ssAttr(d, 'Type');
          const raw = d.textContent;
          if (raw === null || raw === undefined || raw === '') {
            value = null;
          } else if (type === 'Number') {
            const n = parseFloat(raw);
            value = isNaN(n) ? raw : n;
          } else if (type === 'Boolean') {
            value = raw === '1' || raw.toLowerCase() === 'true';
          } else if (type === 'DateTime') {
            const dt = new Date(raw);
            value = isNaN(dt.getTime()) ? raw : dt;
          } else {
            value = raw;
          }
        }
        while (row.length < colIdx) row.push(null);
        row[colIdx] = value;

        // a merged cell occupies extra columns to its right
        const mergeAcross = parseInt(ssAttr(cellEl, 'MergeAcross') || '0', 10);
        colIdx += 1 + (isNaN(mergeAcross) ? 0 : mergeAcross);
      }

      while (rows.length < rowIdx) rows.push([]);
      rows[rowIdx] = row;
      rowIdx += 1;
    }
    rowsBySheet[name] = rows;
  }

  // shape-compatible with what the rest of the app expects from a SheetJS workbook
  return { SheetNames, Sheets: {}, __xlmlRows: rowsBySheet };
}

async function readWorkbookFromFile(file) {
  const buf = await file.arrayBuffer();

  // sniff the first bytes as text to detect SpreadsheetML regardless of extension
  const headText = new TextDecoder('utf-8', { fatal: false }).decode(buf.slice(0, 1000));
  if (isXLML(headText)) {
    const fullText = new TextDecoder('utf-8', { fatal: false }).decode(buf);
    const DP = (typeof DOMParser !== 'undefined') ? DOMParser : null;
    if (!DP) throw new Error('DOMParser non disponibile in questo ambiente.');
    return parseXLML(fullText, DP);
  }

  return XLSX.read(buf, { type: 'array', cellDates: false, raw: true });
}

function findSheet(wb, candidates) {
  const names = wb.SheetNames;
  for (const c of candidates) {
    const exact = names.find(n => n === c);
    if (exact) return exact;
  }
  for (const c of candidates) {
    const ci = names.find(n => n.toLowerCase().trim() === c.toLowerCase().trim());
    if (ci) return ci;
  }
  for (const c of candidates) {
    const partial = names.find(n => n.toLowerCase().includes(c.toLowerCase()));
    if (partial) return partial;
  }
  return null;
}

function sheetRows(wb, sheetName) {
  // XLML workbooks are already stored as column-A-anchored row arrays
  if (wb.__xlmlRows) return wb.__xlmlRows[sheetName] || [];

  const ws = wb.Sheets[sheetName];
  // IMPORTANT: sheet_to_json's header:1 indexes arrays from the sheet's actual
  // used range (ws['!ref']), not always from column A. If column A is entirely
  // empty (common in these exports), index 0 would silently become column B
  // instead of A, shifting every column reference in this file. We force a
  // column-A-anchored array here so index 0 is always A, 1 is always B, etc.
  const ref = ws['!ref'];
  if (!ref) return [];
  const range = XLSX.utils.decode_range(ref);
  const rows = [];
  for (let r = 0; r <= range.e.r; r++) {
    const row = [];
    for (let c = 0; c <= range.e.c; c++) {
      const cell = ws[XLSX.utils.encode_cell({ r, c })];
      row.push(cell ? (cell.v ?? null) : null);
    }
    rows.push(row);
  }
  return rows;
}

/* ============================================================================
   MODULE 1 — CapEx
   ============================================================================ */

/* ----------------------------------------------------------------------------
   CapEx from the raw "Financials Commesse" export

   The three enriched sheets (Fotovoltaico, capitalizzazioni CVS, capitalizzazioni
   SPVs) are themselves built from the raw export. Reading their own formulas back:

     Totale          = Manodopera + Servizi + Materiali + Oneri   (the direct costs)
     Capitalizzazioni = Totale x % ATI
     colonna AI       = Capitalizzazioni x 1,15   for CiviSmart and Fotovoltaico
                      = Capitalizzazioni         for the SPVs (no indirect uplift)
     Fotovoltaico     = one "diretti" row (Capitalizzazioni, summed over the activity
                        codes of the project) and one "indiretti" row (x 0,15)

   What the raw file cannot carry is the anagrafica: the % ATI share, the owning
   company and which of the three groups a project belongs to. Those come from the
   DB commesse; a project that has none is flagged rather than guessed at.

   Rows are capitalised when their activity code is NOT one of those CVS BU takes —
   i.e. the CONSTRUCTION and PREPARATION families.
   ---------------------------------------------------------------------------- */
function capexFromRaw(wb, db) {
  const parsed = readCommesseRows(wb, db);
  if (parsed.error) return { error: parsed.error };

  const whitelist = new Set(db.cvsBuWhitelist || []);
  const rate = db.capexIndirectRate ?? 0.15;
  const fvAgg = {}, csAgg = {};

  for (const rec of parsed.records) {
    const family = activityCodeFamily(rec.act);
    if (whitelist.has(family)) continue;               // belongs to CVS BU, not CapEx
    if (family !== 'CONSTRUCTION' && family !== 'PREPARATION') continue;
    const totale = rec.dc || 0;
    if (!totale) continue;

    const hist = (db.capexProjectDB && db.capexProjectDB[rec.pid]) || null;
    const { second } = projectIdSegments(rec.pid);
    const group = hist?.group || (second === 'PHV' ? 'FV' : 'CVS');
    // Commesse senza anagrafica CapEx: % ATI assunta a 1, Società a "Civismart"
    // più sotto — nessuna segnalazione per revisione.
    const ati = hist?.pctATI ?? 1;

    const cap = totale * ati;
    const name = rec.name || '';
    const comuneRaw = name.split(':')[0];
    const dettaglio = name.includes(':') ? name.slice(name.indexOf(':') + 1) : name;

    if (group === 'FV') {
      if (!fvAgg[rec.pid]) fvAgg[rec.pid] = { diretti: 0, indiretti: 0, name };
      fvAgg[rec.pid].diretti += cap;
      fvAgg[rec.pid].indiretti += cap * rate;
    } else {
      const key = rec.pid + '\u0001' + rec.act;
      if (!csAgg[key]) {
        csAgg[key] = { pid: rec.pid, act: rec.act, ai: 0, aj: hist?.societa || null, comuneRaw, dettaglio };
      }
      csAgg[key].ai += group === 'SPV' ? cap : cap * (1 + rate);
    }
  }

  return { fvAgg, csAgg, isRaw: true, sheetName: parsed.sheetName };
}

function processCapEx(wb, db) {
  const fvSheetName = findSheet(wb, ['Fotovoltaico']);
  const cvsSheetName = findSheet(wb, ['capitalizzazioni CVS']);
  const spvSheetName = findSheet(wb, ['capitalizzazioni SPVs']);
  const enriched = fvSheetName && cvsSheetName && spvSheetName;

  let rawBuilt = null;
  if (!enriched) {
    rawBuilt = capexFromRaw(wb, db);
    if (rawBuilt.error) {
      const missing = [];
      if (!fvSheetName) missing.push('Fotovoltaico');
      if (!cvsSheetName) missing.push('capitalizzazioni CVS');
      if (!spvSheetName) missing.push('capitalizzazioni SPVs');
      return {
        error: `Il file non contiene né i fogli elaborati (${missing.join(', ')}) né l'export grezzo "Financials Commesse". ` +
          `Fogli disponibili: ${wb.SheetNames.join(', ')}. Dettaglio: ${rawBuilt.error}`,
      };
    }
  }

  const results = [];
  const newComuni = new Set();

  function resolveComune(rawComune, projectId) {
    // The CVS BU register holds the same anagrafica keyed by project code, which is an
    // exact match rather than a text match on the raw description — so it comes first,
    // and it carries the corrections made there.
    const cvs = db.cvsBuProjectDB && db.cvsBuProjectDB[projectId];
    if (cvs && cvs.comune) {
      return {
        comune: cvs.comune, bu: cvs.bu || db.comuneToBU[cvs.comune] || null,
        comuneSource: 'anagrafica CVS BU (per codice commessa)',
        buSource: cvs.bu ? 'anagrafica CVS BU' : null,
      };
    }
    const clean = db.comuneCleanDB[rawComune];
    if (clean) {
      const bu = db.comuneToBU[clean] || null;
      return { comune: clean, bu, comuneSource: 'storico CapEx', buSource: bu ? 'storico' : null };
    }
    const guess = stripComuneDiPrefix(rawComune || '');
    const bu = db.comuneToBU[guess] || null;
    newComuni.add(rawComune);
    return { comune: guess, bu, comuneSource: 'nuovo (regola Title Case)', buSource: bu ? 'storico (nome combacia)' : null };
  }

  // ---- Fotovoltaico: aggregate per project (from the enriched sheet or the raw export) ----
  const fvAgg = {};
  if (enriched) {
    const fvRows = sheetRows(wb, fvSheetName);
    for (let i = 5; i < fvRows.length; i++) {
      const row = fvRows[i];
      if (!row) continue;
      const pid = row[1];
      if (!pid) continue;
      if (!fvAgg[pid]) fvAgg[pid] = { diretti: 0, indiretti: 0, name: row[2] };
      fvAgg[pid].diretti += (row[10] || 0);
      fvAgg[pid].indiretti += (row[13] || 0);
    }
  } else {
    Object.assign(fvAgg, rawBuilt.fvAgg);
  }
  // pre-compute per-project static fields once, then emit in two grouped passes
  // (all diretti first, then all indiretti, same project order both times) —
  // matches the real sheet's layout, not an interleaved diretti/indiretti/diretti/indiretti order
  const fvComputed = Object.entries(fvAgg).map(([pid, agg]) => {
    const cls = classifyCapexProject(pid, db);
    const comuneRaw = (agg.name || '').split(':')[0];
    const res = resolveComune(comuneRaw, pid);
    let { comune, bu } = res;
    let buNote = null;
    const cad = lookupCadastral(pid, db);
    if (!bu && cad && cad.bu) {
      bu = cad.bu;
      buNote = `BU dedotta dal codice catastale ${cad.code} (${cad.comune}) contenuto nel Project ID`;
    } else if (bu && cad && cad.bu && cad.bu !== bu) {
      buNote = `BU DA VERIFICARE: nel DB commesse è "${bu}", ma il codice catastale ${cad.code} corrisponde a ${cad.comune} → "${cad.bu}". Valore tenuto: quello del DB commesse.`;
    }
    return { pid, agg, cls, comune, bu, buNote, buMismatch: !!(buNote && buNote.startsWith('BU DA VERIFICARE')) };
  });

  function emitFVRow(item, kind, val) {
    const { pid, agg, cls, comune, bu, buNote, buMismatch } = item;
    const reasons = [];
    if (!bu) reasons.push('BU non trovata per questo comune — verificare manualmente');
    if (!cls.service) reasons.push(`segmenti del Project ID "${pid}" non riconosciuti — Tipo servizio/contratto da inserire a mano`);
    if (buMismatch) reasons.push(buNote);
    results.push({
      key: nextKey(), status: (bu && cls.service && !buMismatch) ? 'auto' : 'flag',
      reason: reasons.join(' · ') || null,
      fields: {
        sino: '', chiave: '', projectId: pid, comuneRaw: kind, comuneClean: comune, bu: bu || '?',
        service: cls.service || '?', contract: cls.contract || '?', dettaglio: agg.name,
        activityCode: '', materiali: '', servizi: '', manodopera: '', oneri: '', totale: '', pctATI: '',
        capitalizzazioni: '', importo: val, societa: 'Civismart',
        stato: buMismatch ? 'BU da verificare' : (!bu || !cls.service ? 'da rivedere' : ''),
      },
      matchNote: [
        'Fotovoltaico → Civismart sempre',
        cls.source ? `classificazione: ${cls.source}` : null,
        buNote && !buMismatch ? buNote : null,
      ].filter(Boolean).join(' · '),
    });
  }
  for (const item of fvComputed) emitFVRow(item, 'diretti', item.agg.diretti);
  for (const item of fvComputed) emitFVRow(item, 'indiretti', item.agg.indiretti);

  // ---- capitalizzazioni CVS + SPVs: key = (ProjectID, ActivityCode), sum duplicates ----
  function processCS(rows, aiCol, ajCol) {
    const agg = {};
    for (let i = 5; i < rows.length; i++) {
      const row = rows[i];
      if (!row) continue;
      const pid = row[1];
      if (!pid) continue;
      const act = row[0];
      const key = pid + '\u0001' + act;
      if (!agg[key]) agg[key] = { pid, act, ai: 0, aj: row[ajCol], comuneRaw: row[3], dettaglio: row[4] };
      agg[key].ai += (row[aiCol] || 0);
    }
    return agg;
  }
  const csEntries = enriched
    ? [...Object.values(processCS(sheetRows(wb, cvsSheetName), 13, 14)),
       ...Object.values(processCS(sheetRows(wb, spvSheetName), 12, 13))]
    : Object.values(rawBuilt.csAgg);

  for (const agg of csEntries) {
    const cls = classifyCapexProject(agg.pid, db);
    const { comune, bu, comuneSource, buSource } = resolveComune(agg.comuneRaw, agg.pid);
    const hist = db.capexProjectDB && db.capexProjectDB[agg.pid];

    // history (DB commesse) wins over the raw file when the two disagree
    let societa = agg.aj;
    const notes = [];
    if (hist && hist.societa && agg.aj && hist.societa !== agg.aj) {
      societa = hist.societa;
      notes.push(`Società da storico ("${hist.societa}"); il file grezzo riporta "${agg.aj}"`);
    } else if (!societa) {
      // the raw export carries no company: take it from the DB commesse
      if (hist && hist.societa) {
        societa = hist.societa;
        notes.push('Società dal DB commesse (non presente nel file grezzo)');
      } else {
        // nessuno storico e nessun dato nel file grezzo: default silenzioso,
        // nessuna segnalazione per revisione (vedi sopra).
        societa = 'Civismart';
      }
    }

    // same cadastral cross-check as CVS BU: fill a missing BU from the code in the
    // Project ID, and report a mismatch with the recorded one rather than hiding it
    const cad = lookupCadastral(agg.pid, db);
    let buFinal = bu;
    let buMismatch = false;
    if (!buFinal && cad && cad.bu) {
      buFinal = cad.bu;
      notes.push(`BU dedotta dal codice catastale ${cad.code} (${cad.comune}) contenuto nel Project ID`);
    } else if (buFinal && cad && cad.bu && cad.bu !== buFinal) {
      buMismatch = true;
      notes.push(`BU DA VERIFICARE: nel DB commesse è "${buFinal}", ma il codice catastale ${cad.code} corrisponde a ${cad.comune} → "${cad.bu}". Valore tenuto: quello del DB commesse.`);
    }

    // Commesse assenti dall'anagrafica CapEx non vengono più segnalate per
    // revisione: % ATI resta assunta a 1 e Società a "Civismart" (vedi capexFromRaw),
    // silenziosamente, su richiesta esplicita.
    const flagged = !buFinal || !cls.service || buMismatch;
    const reasons = [];
    if (!cls.service) reasons.push(`segmenti del Project ID "${agg.pid}" non riconosciuti — Tipo servizio/contratto da inserire a mano`);
    if (!buFinal) reasons.push('BU non determinabile per questo comune/cliente');
    if (buMismatch) reasons.push(notes[notes.length - 1]);

    results.push({
      key: nextKey(), status: flagged ? 'flag' : 'auto',
      reason: reasons.join(' · ') || null,
      fields: {
        sino: '', chiave: '', projectId: agg.pid, comuneRaw: agg.comuneRaw, comuneClean: comune, bu: buFinal || '?',
        service: cls.service || '?', contract: cls.contract || '?', dettaglio: agg.dettaglio,
        activityCode: agg.act, materiali: '', servizi: '', manodopera: '', oneri: '', totale: '', pctATI: '',
        capitalizzazioni: '', importo: agg.ai, societa,
        stato: buMismatch ? 'BU da verificare' : (flagged ? 'da rivedere' : ''),
      },
      matchNote: [
        `Comune: ${comuneSource}`,
        buSource ? `BU: ${buSource}` : null,
        cls.source ? `classificazione: ${cls.source}` : null,
        ...notes,
      ].filter(Boolean).join(' · '),
    });
  }

  return {
    results,
    columns: [
      { key: 'sino', label: 'Sì/No (R)' },
      { key: 'chiave', label: 'Chiave (S)' },
      { key: 'projectId', label: 'Project ID (T)' },
      { key: 'comuneRaw', label: 'Comune (U)' },
      { key: 'comuneClean', label: 'Comune (V)' },
      { key: 'bu', label: 'BU (W)' },
      { key: 'service', label: 'Type of service (X)' },
      { key: 'contract', label: 'Type of Contract (Y)' },
      { key: 'dettaglio', label: 'Dettaglio commessa (Z)' },
      { key: 'activityCode', label: 'Activity Code (AA)' },
      { key: 'materiali', label: '04 - Materiali (AB)' },
      { key: 'servizi', label: '02 - Servizi (AC)' },
      { key: 'manodopera', label: '03 - Manodopera (AD)' },
      { key: 'oneri', label: '01 - Oneri (AE)' },
      { key: 'totale', label: 'Totale (AF)' },
      { key: 'pctATI', label: '% ATI (AG)' },
      { key: 'capitalizzazioni', label: 'Capitalizzazioni (AH)' },
      { key: 'importo', label: 'Capitalizzazione + Costi indiretti (AI)', numeric: true },
      { key: 'societa', label: 'Società (AJ)' },
      // kept last on purpose: R:AJ stay contiguous for a straight paste into the sheet
      { key: 'stato', label: 'Stato' },
      { key: 'nota', label: 'Nota' },
    ],
    newEntries: { comuni: [...newComuni] },
  };
}

/* ============================================================================
   MODULE 2 — BDV
   ============================================================================ */

// Propose a classification for an account code the BDV sheet has never seen.
// Two signals are available, and they are good at different things:
//   - the code prefix: the chart of accounts is structured, so neighbouring codes
//     share Società / Quadro / Conto I almost perfectly
//   - the account name from the raw file: "F/Amm Avviamento" tells you it's
//     Avviamento far better than its code neighbours do
// Measured by leave-one-out over the 441 known accounts, the per-field winners are:
//   Società 100% · Quadro 99.8% · Cluster II 92.5% · Ricla 80% · Conto I 74.6% · Conto II 69.2%
// so each field uses whichever signal wins for it. All six right at once only ~55%
// of the time: these are proposals to review, never values to trust blind. Every one
// is flagged and marked "new".
const BDV_FIELDS = ['societa', 'quadro', 'ricla', 'clusterII', 'contoI', 'contoII'];
const BDV_NAME_DRIVEN_FIELDS = new Set(['ricla', 'clusterII', 'contoII']);
const BDV_NAME_WEIGHT = 6;
const BDV_STOPWORDS = new Set(['di','e','a','da','in','su','per','il','la','le','i','gli','del','della','dei','delle','c','f','amm','ft','ric']);

function bdvNameTokens(s) {
  const cleaned = (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ');
  return new Set(cleaned.split(' ').filter(t => t.length > 2 && !BDV_STOPWORDS.has(t)));
}

function sharedPrefixLen(a, b) {
  let n = 0;
  while (n < Math.min(a.length, b.length) && a[n] === b[n]) n++;
  return n;
}

function bdvNeighbours(code, name, bdvFull, nameWeight) {
  const tk = bdvNameTokens(name);
  let bestScore = -1, best = [];
  for (const [other, rec] of Object.entries(bdvFull)) {
    if (!/^\d+$/.test(other) || other === code) continue;
    let score = sharedPrefixLen(code, other);
    if (nameWeight && tk.size) {
      const ot = bdvNameTokens(rec?.nome);
      let inter = 0;
      for (const t of tk) if (ot.has(t)) inter++;
      const union = tk.size + ot.size - inter;
      if (union > 0) score += (inter / union) * nameWeight;
    }
    if (score > bestScore) { bestScore = score; best = [other]; }
    else if (score === bestScore) best.push(other);
  }
  return { best, bestScore };
}

function bdvVote(bdvFull, nbs, field) {
  const counts = new Map();
  for (const nb of nbs) {
    const k = String(bdvFull[nb]?.[field] ?? '');
    counts.set(k, (counts.get(k) || 0) + 1);
  }
  let topKey = null, topCount = 0;
  for (const [k, c] of counts) if (c > topCount) { topKey = k; topCount = c; }
  const value = nbs.map(nb => bdvFull[nb]?.[field]).find(v => String(v ?? '') === topKey) ?? '';
  return { value, confidence: topCount / nbs.length };
}

function proposeBdvClassification(code, name, bdvFull) {
  if (!bdvFull || !/^\d+$/.test(code)) return null;

  const byPrefix = bdvNeighbours(code, name, bdvFull, 0);
  const byName = bdvNeighbours(code, name, bdvFull, BDV_NAME_WEIGHT);
  if (!byPrefix.best.length) return null;

  const prefixLen = sharedPrefixLen(code, byPrefix.best[0]);
  if (prefixLen < 2) return null;

  const fields = {};
  const confidence = {};
  for (const f of BDV_FIELDS) {
    const nbs = BDV_NAME_DRIVEN_FIELDS.has(f) && byName.best.length ? byName.best : byPrefix.best;
    const { value, confidence: c } = bdvVote(bdvFull, nbs, f);
    fields[f] = value;
    confidence[f] = c;
  }

  const weak = BDV_FIELDS.filter(f => confidence[f] < 0.6);
  return {
    fields, confidence, prefixLen, weak,
    basedOn: byPrefix.best.slice(0, 3),
    nameMatch: byName.best.slice(0, 2),
  };
}

function processBDV(wbTB, wbPL, db, wbDG) {
  // ---- optional second company: aggregate its balance onto CVS accounts ----
  let dgByCode = {}, dgByClass = {}, dgExtra = [], dgSheetName = null, dgTotal = 0;
  if (wbDG) {
    const parsedDG = readDeGiorgiBridge(wbDG, db);
    if (parsedDG.error) return { error: parsedDG.error };
    dgSheetName = parsedDG.sheetName;

    for (const rec of parsedDG.records) {
      dgTotal += rec.value;

      // revenue: 620201 is never carried on the account itself — the BDV splits it
      // by business class, so the company's revenue has to be split the same way
      if (rec.cvsCode === '620201') {
        // the agreed Ricla transcoding maps each of the company's revenue accounts
        // to a CVS business class
        const ricla = db.degiorgiRevenueStream && db.degiorgiRevenueStream[rec.dgCode];
        const cls = rec.stream || (ricla && ricla.stream) || null;
        if (cls) {
          dgByClass[cls] = (dgByClass[cls] || 0) + rec.value;
        } else {
          // not in the agreed transcoding: still propose a class (the closest by
          // account name among the classes already in use) rather than leaving it blank
          const classes = [...new Set(Object.values(db.degiorgiRevenueStream || {})
            .map(x => x.stream).filter(Boolean))];
          const guess = proposeByName(rec.dgDesc, null,
            Object.fromEntries(classes.map(c => [c, { nome: c, quadro: 'CE' }])));
          const proposed = guess ? guess.code : (classes[0] || null);
          if (proposed) dgByClass[proposed] = (dgByClass[proposed] || 0) + rec.value;
          dgExtra.push({
            code: rec.dgCode, nome: rec.dgDesc, value: 0, quadro: DG_SECTION_QUADRO[rec.section],
            stato: 'da rivedere',
            reason: proposed
              ? `ricavo non presente nella transcodifica concordata — attribuito in via PROPOSTA alla classe "${proposed}" (${fmtEUR(rec.value)} €): da confermare`
              : `ricavo senza classe di business assegnata (${fmtEUR(rec.value)} €) — va attribuito a una classe prima di entrare nel BDV`,
          });
        }
        continue;
      }

      if (rec.cvsCode && db.bdvAccounts && (rec.cvsCode in db.bdvAccounts)) {
        dgByCode[rec.cvsCode] = (dgByCode[rec.cvsCode] || 0) + rec.value;
        continue;
      }

      // an account previously flagged "Da creare" may since have been created in the
      // BDV under the originating company's own code — the DB commesse is the source
      // of truth, so once it is there it is a normal account, not a new one
      if (!rec.cvsCode && db.bdvAccounts && (rec.dgCode in db.bdvAccounts)) {
        dgByCode[rec.dgCode] = (dgByCode[rec.dgCode] || 0) + rec.value;
        continue;
      }

      // no CVS account yet: keep the originating company's code and description
      // and propose the managerial reclassification by analogy
      const quadro = DG_SECTION_QUADRO[rec.section];
      const isNumeric = /^\d+$/.test(rec.cvsCode || '');
      const code = isNumeric ? rec.cvsCode : rec.dgCode;
      const nome = isNumeric ? (rec.cvsDesc || rec.dgDesc) : rec.dgDesc;
      const prop = isNumeric
        ? proposeBdvClassification(code, nome, db.bdvFull)
        : null;
      const byName = prop ? null : proposeByName(rec.dgDesc, quadro, db.bdvFull);

      dgExtra.push({
        code, nome, value: rec.value, quadro,
        fields: prop ? prop.fields : (byName ? byName.fields : null),
        stato: isNumeric ? 'da rivedere' : 'da creare',
        reason: prop
          ? `conto presente nel piano dei conti ma non ancora nel BDV — classificazione proposta (simili: ${prop.basedOn.join(', ')}): da confermare`
          : byName
            ? `conto NUOVO da creare: codice e descrizione mantenuti da ${nome ? 'De Giorgi' : 'origine'}; classificazione proposta per analogia con ${byName.code} (${db.bdvFull[byName.code].nome}): da confermare`
            : 'conto NUOVO da creare: nessun conto simile in archivio, classificazione da inserire a mano',
      });
    }
  }

  // ---- trial balance: find the data sheet (first sheet with an "Account" style layout) ----
  let tbSheetName = wbTB.SheetNames.find(n => /bilancio|verifica|trial/i.test(n)) || wbTB.SheetNames[0];
  const tbRows = sheetRows(wbTB, tbSheetName);

  const tb = {};
  const tbNames = {};
  for (const row of tbRows) {
    if (!row || !row[0] || typeof row[0] !== 'string' || !row[0].includes(' - ')) continue;
    const parts = row[0].split(' - ');
    const codeStr = parts[0].trim();
    // the name is everything after the first separator (names can contain " - " themselves)
    const nameStr = parts.slice(1).join(' - ').trim();
    const debit = row[1] || 0;
    const credit = row[2] || 0;
    tb[codeStr] = (tb[codeStr] || 0) + (debit - credit);
    if (nameStr && !tbNames[codeStr]) tbNames[codeStr] = nameStr;
  }
  if (Object.keys(tb).length === 0) {
    return { error: `Non trovo righe "codice - nome" nel foglio "${tbSheetName}" del Bilancio di Verifica. Fogli disponibili: ${wbTB.SheetNames.join(', ')}` };
  }

  // ---- P&L by class: locate header row + the 620201 Ricavi row ----
  let plSheetName = wbPL.SheetNames.find(n => /profit|conto economico|p&l/i.test(n)) || wbPL.SheetNames[0];
  const plRows = sheetRows(wbPL, plSheetName);
  let headerRow = plRows.find(r => r && r[0] === 'Financial Row');
  let ricaviRow = plRows.find(r => r && typeof r[0] === 'string' && r[0].startsWith('620201'));

  const classValues = {};
  if (headerRow && ricaviRow) {
    for (let i = 1; i < headerRow.length; i++) {
      const cls = headerRow[i];
      if (!cls || cls === 'Total') continue;
      classValues[cls] = -(ricaviRow[i] || 0);
    }
  }

  const results = [];
  const classNameSet = new Set(Object.keys(classValues).length ? Object.keys(classValues) : (headerRow ? headerRow.slice(1).filter(c => c && c !== 'Total') : []));

  function emitRow(code, tmpl, valore, status, reason, matchNote, stato, dgOverride) {
    const dg = dgOverride !== undefined
      ? dgOverride
      : (dgByCode[code] ?? dgByClass[code] ?? 0);
    results.push({
      key: nextKey(), status, reason,
      fields: {
        societa: tmpl?.societa ?? 'CVS', quadro: tmpl?.quadro ?? (code === '620201' || classNameSet.has(code) ? 'CE' : ''),
        altro: tmpl?.altro ?? '', ricla: tmpl?.ricla ?? (classNameSet.has(code) ? 'Revenue by class' : ''),
        codice: code, nome: tmpl?.nome ?? code, clusterII: tmpl?.clusterII ?? '',
        contoI: tmpl?.contoI ?? '', contoII: tmpl?.contoII ?? '',
        valore: Math.round(valore * 100) / 100,
        valoreDG: Math.round((dg || 0) * 100) / 100,
        stato: stato ?? '',
      },
      matchNote,
    });
  }

  for (const [code, info] of Object.entries(db.bdvAccounts)) {
    if (classNameSet.has(code)) continue; // handled exclusively by the class-split rows below
    const tmpl = db.bdvFull ? db.bdvFull[code] : null;
    if (code === '620201') {
      emitRow(code, tmpl, 0, 'auto', null, 'spacchettato per classe sotto');
      continue;
    }
    const value = tb[code];
    emitRow(code, tmpl, value === undefined ? 0 : value, 'auto', null,
      value === undefined ? 'assente nel grezzo → 0 (nessuna attività)' : 'Bilancio di Verifica');
  }
  for (const [cls, val] of Object.entries(classValues)) {
    emitRow(cls, null, val, 'auto', null, '620201 Ricavi, per classe');
  }

  // ---- accounts present in the raw file but not yet in the BDV sheet ----
  const unknown = Object.keys(tb).filter(c => !(c in db.bdvAccounts) && Math.abs(tb[c]) > 0.01);
  for (const code of unknown) {
    const nome = tbNames[code] || code;
    const proposal = proposeBdvClassification(code, nome, db.bdvFull);
    const tmpl = proposal ? { ...proposal.fields, nome } : { nome };

    const LABELS = { societa: 'Società', quadro: 'Quadro', ricla: 'Ricla', clusterII: 'Cluster II', contoI: 'Conto I', contoII: 'Conto II' };
    let reason;
    if (proposal) {
      reason = `NUOVO conto — classificazione proposta (simili: ${proposal.basedOn.join(', ')}): da confermare`;
      if (proposal.weak.length) {
        reason += ` · meno sicuri: ${proposal.weak.map(f => LABELS[f]).join(', ')}`;
      }
    } else {
      reason = 'NUOVO conto — nessun conto simile in archivio, classificazione da inserire a mano';
    }

    emitRow(code, tmpl, tb[code], 'flag', reason, null, 'new');
  }

  // ---- De Giorgi accounts that have no row in the BDV yet ----
  for (const x of dgExtra) {
    const tmpl = { ...(x.fields || {}), nome: x.nome, quadro: x.fields?.quadro || x.quadro };
    emitRow(x.code, tmpl, 0, 'flag', x.reason, 'solo De Giorgi', x.stato, x.value);
  }

  const monthLabel = 'Valore mese';
  const columns = [
    { key: 'societa', label: 'Società (B)' },
    { key: 'quadro', label: 'Quadro (C)' },
    { key: 'altro', label: 'Altro (D)' },
    { key: 'ricla', label: 'Ricla MG esteso (E)' },
    { key: 'codice', label: 'Codice Conto (F)' },
    { key: 'nome', label: 'Conto COGE (G)' },
    { key: 'clusterII', label: 'Cluster II (H)' },
    { key: 'contoI', label: 'Conto COGE I livello (I)' },
    { key: 'contoII', label: 'Conto COGE II livello (J)' },
    { key: 'valore', label: `${monthLabel} € — CVS`, numeric: true },
  ];
  if (wbDG) columns.push({ key: 'valoreDG', label: `${monthLabel} € — De Giorgi`, numeric: true });
  // kept last on purpose: the account columns stay contiguous for a straight paste
  columns.push({ key: 'stato', label: 'Stato' });
  columns.push({ key: 'nota', label: 'Nota' });

  return {
    results, columns,
    tbSheetName, plSheetName, dgSheetName,
    dgTotal: Math.round(dgTotal * 100) / 100,
  };
}

/* ----------------------------------------------------------------------------
   De Giorgi bridge (optional second company)

   The acquired company's trial balance arrives already bridged: its own account
   code and description, the balance, and the CVS account it maps onto. Accounts
   marked "Da creare" have no CVS account yet — those keep the ORIGINATING
   company's code and description, and only their managerial reclassification is
   proposed by analogy.

   Balances arrive as positive numbers under four section headings. The BDV works
   in Debit - Credit, so PASSIVO and RICAVI are negated on the way in; that is what
   makes the two companies' columns summable and the whole thing square to zero.
   ---------------------------------------------------------------------------- */

const DG_SECTION_SIGN = { ATTIVO: 1, COSTI: 1, PASSIVO: -1, RICAVI: -1 };
const DG_SECTION_QUADRO = { ATTIVO: 'SP', PASSIVO: 'SP', COSTI: 'CE', RICAVI: 'CE' };

function readDeGiorgiBridge(wb, db) {
  const sheetName = findSheet(wb, ['Bridge']) || wb.SheetNames[0];
  const rows = sheetRows(wb, sheetName);

  // locate the header row: the company's own "Codice"/"Descrizione" plus the CVS "Codice"
  let hdr = -1, cols = null;
  for (let i = 0; i < Math.min(rows.length, 20); i++) {
    const cells = (rows[i] || []).map(v => (v ?? '').toString().trim().toLowerCase());
    const first = cells.indexOf('codice');
    if (first < 0) continue;
    const second = cells.indexOf('codice', first + 1);
    if (second < 0) continue;
    cols = {
      dgCode: first,
      dgDesc: cells.indexOf('descrizione'),
      saldo: cells.findIndex(c => c.startsWith('saldo')),
      cvsCode: second,
      cvsDesc: cells.indexOf('descrizione', second),
      note: cells.findIndex(c => c === 'note'),
      stream: cells.findIndex(c => c.includes('business stream')),
    };
    hdr = i;
    break;
  }
  if (hdr < 0 || cols.saldo < 0) {
    return { error: `Nel foglio "${sheetName}" non trovo le intestazioni attese del bridge ("Codice", "Descrizione", "Saldo ...", "Codice" del conto CVS). Fogli disponibili: ${wb.SheetNames.join(', ')}` };
  }

  const records = [];
  let section = null;
  for (let i = hdr + 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row) continue;
    const dgCode = row[cols.dgCode];
    const dgDesc = cols.dgDesc >= 0 ? row[cols.dgDesc] : null;
    const saldo = row[cols.saldo];

    // section heading: a label with no balance and no CVS account
    if (dgCode && dgDesc && (saldo === null || saldo === undefined) && !row[cols.cvsCode]) {
      const label = dgDesc.toString().trim().toUpperCase();
      if (DG_SECTION_SIGN[label] !== undefined) section = label;
      continue;
    }
    if (!dgCode || typeof saldo !== 'number' || !section) continue;

    records.push({
      section,
      dgCode: dgCode.toString().trim(),
      dgDesc: (dgDesc ?? '').toString().trim(),
      value: saldo * DG_SECTION_SIGN[section],
      cvsCode: row[cols.cvsCode] != null ? row[cols.cvsCode].toString().trim() : null,
      cvsDesc: cols.cvsDesc >= 0 ? row[cols.cvsDesc] : null,
      note: cols.note >= 0 ? row[cols.note] : null,
      stream: cols.stream >= 0 && row[cols.stream] ? row[cols.stream].toString().trim() : null,
    });
  }

  if (!records.length) {
    return { error: `Nel foglio "${sheetName}" non trovo righe di conto sotto le sezioni ATTIVO / PASSIVO / COSTI / RICAVI.` };
  }
  return { records, sheetName };
}

// closest known account by name, used for accounts that have no CVS code at all
function proposeByName(name, quadro, bdvFull) {
  const tk = bdvNameTokens(name);
  if (!tk.size) return null;
  let best = null, score = 0;
  for (const [code, rec] of Object.entries(bdvFull)) {
    if (quadro && rec.quadro && rec.quadro !== quadro) continue;
    const ot = bdvNameTokens(rec.nome);
    let inter = 0;
    for (const t of tk) if (ot.has(t)) inter++;
    const union = tk.size + ot.size - inter;
    if (!union) continue;
    const s = inter / union;
    if (s > score) { score = s; best = code; }
  }
  return best ? { code: best, fields: Object.fromEntries(BDV_FIELDS.map(f => [f, bdvFull[best][f]])), score } : null;
}


/* ============================================================================
   MODULE 3 — SGP
   ============================================================================ */

function processSGP(wb, db) {
  const sheetName = findSheet(wb, ['SGP+SPV']);
  if (!sheetName) {
    return { error: `Foglio "SGP+SPV" non trovato. Fogli disponibili: ${wb.SheetNames.join(', ')}` };
  }
  const rows = sheetRows(wb, sheetName);
  const results = [];
  const newTexts = [];

  let currentSign = null;
  let inPL = false;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i] || [];
    const b = row[1];
    const text = (b || '').toString().trim();
    const rowNum = i + 1;

    const isATTIVO = text === 'ATTIVO';
    const isPASSIVO = text === 'PASSIVO';
    const isCE = text.includes('CONTO ECONOMICO') || text === 'ECONOMICO';

    let code = null, status = 'auto', reason = null, matchNote = null;
    if (b !== null && b !== undefined) {
      if (db.sgpLegend.hasOwnProperty(b)) {
        code = db.sgpLegend[b];
        matchNote = 'storico (mese precedente)';
      } else if (isATTIVO || isPASSIVO || isCE || text === '' || /^(ATTIVO|PASSIVO|RICAVI|COSTI)/i.test(text)) {
        code = 0;
        matchNote = 'riga titolo/sezione';
      } else {
        code = null;
        status = 'flag';
        reason = 'testo mai visto — assegnare un codice';
        newTexts.push(b);
      }
    }

    // H formula: determined BEFORE updating section state for title rows themselves
    let hFormula = null;
    if (!inPL && currentSign && b !== null && text !== 'ATTIVO' && text !== 'PASSIVO') {
      hFormula = currentSign === '+' ? `=+G${rowNum}` : `=-G${rowNum}`;
    }

    // update section state AFTER computing H for this row
    if (isATTIVO) { currentSign = '+'; inPL = false; }
    else if (isPASSIVO) { currentSign = '-'; inPL = false; }
    else if (isCE) { inPL = true; currentSign = null; }

    if (b === null && row[6] === undefined) continue; // fully blank row

    results.push({
      key: nextKey(), status, reason,
      fields: {
        row: rowNum, codeA: code === null ? '?' : code, text: b,
        sgp: row[2], spv: row[3], aggregato: row[4], rettifiche: row[5], consolidato: row[6],
        formulaH: hFormula || '',
      },
      matchNote,
    });
  }

  return {
    results,
    columns: [
      { key: 'codeA', label: 'A · Chiave' },
      { key: 'text', label: 'B · Voce' },
      { key: 'sgp', label: 'C · SGP', numeric: true },
      { key: 'spv', label: 'D · SPV', numeric: true },
      { key: 'aggregato', label: 'E · AGGREGATO', numeric: true },
      { key: 'rettifiche', label: 'F · RETTIFICHE', numeric: true },
      { key: 'consolidato', label: 'G · CONSOLIDATO', numeric: true },
      { key: 'formulaH', label: 'H' },
      // kept last on purpose: A:H stay contiguous for a straight paste into the sheet
      { key: 'stato', label: 'Stato' },
      { key: 'nota', label: 'Nota' },
    ],
    newEntries: { testi: newTexts },
    sheetName,
  };
}

/* ----------------------------------------------------------------------------
   Cadastral (Belfiore) code from the Project ID

   A Project ID ends "...-<codice catastale>-<progressivo>", e.g. EPC-IPU-A952-01.
   The penultimate segment is the comune's cadastral code, so it identifies the
   location — and therefore the BU — even when the customer is a private company
   and the project name carries no comune at all ("Tigros Servizi Immobiliari Srl").

   The lookup covers every Italian comune. Cross-checked against the 223 cadastral
   codes taken from concession projects already in the DB commesse: 220 agree; the
   3 that differ are errors in those historical rows, not in the table.
   ---------------------------------------------------------------------------- */
function cadastralCode(pid) {
  const parts = (pid || '').split('-');
  if (parts.length < 2) return null;
  const cand = parts[parts.length - 2];
  return /^[A-Z]\d{3}$/.test(cand) ? cand : null;
}

function lookupCadastral(pid, db) {
  const code = cadastralCode(pid);
  if (!code || !db.catastale) return null;
  const entry = db.catastale[code];
  if (!entry) return { code, bu: null, comune: null };
  return {
    code,
    bu: (db.catastaleBU || [])[Number(entry[0])] || null,
    comune: entry.slice(1),
  };
}

/* ============================================================================
   MODULE 4 — CVS BU
   ============================================================================ */

/* ----------------------------------------------------------------------------
   CVS BU input adapters

   Two layouts of the same NetSuite "Financials Commesse" report arrive here:

   A) "Elab 3" — the enriched sheet, already worked by hand:
      A=Activity Code  B=NEW Activity Code  C=Project ID  D=Project Name
      E=Manodopera  F=Ricavi  G=Servizi  H=Materiali  I=Oneri
      Flat: every row repeats Project ID and name.

   B) the raw export (e.g. "FinancialsCommesse_<date>.xlsx"):
      A=Project ID  B=Project Name  C=Activity Code Tr.
      then one "Importo" column per cost/revenue category, whose meaning is
      written in the row ABOVE the header row, in a different order.
      Grouped: Project ID and name appear only on a project's first row.

   Both are normalized to { pid, name, act, newact, ricavi, dc } so everything
   downstream stays identical. Columns are located by their header text, never by
   position, because the two layouts order the amount columns differently.
   ---------------------------------------------------------------------------- */

// NetSuite activity codes are being renamed, and the raw export shows only the leaf
// name where Elab 3 shows the full "PARENT : Child" path. This table maps a code to
// the family that decides whether it belongs in CVS BU. It is used ONLY for that
// decision — the activity code itself is always written out exactly as it appears in
// the source file, so the new codes stay visible and rows are never merged together.
// Family assignments confirmed by Enrico:
//   "Operation & Maintenance" is the new name under Operation  -> in scope
//   "Construction & Operational" sits under Construction       -> out of scope
const CVSBU_CODE_FAMILY = {
  // operational family
  'OPERATIONAL': 'OPERATIONAL',
  'Operation': 'OPERATIONAL',
  'Operation & Maintenance': 'OPERATIONAL',
  'OPERATION & MAINTENANCE': 'OPERATIONAL',
  // extra lavori family
  'EXTRA LAVORI': 'EXTRA LAVORI',
  'Spot': 'EXTRA LAVORI : Spot',
  'EXTRA LAVORI : Spot': 'EXTRA LAVORI : Spot',
  // generico
  'GENERICO': 'GENERICO',
  // unclassified transactions ("no activity code o simili")
  'Unknown': '- No Activity Code -',
  'NO ACTIVITY CODE': '- No Activity Code -',
  'No Activity Code': '- No Activity Code -',
  '- No Activity Code -': '- No Activity Code -',
  // construction family — out of scope for CVS BU
  'CONSTRUCTION': 'CONSTRUCTION',
  'Construction': 'CONSTRUCTION',
  'Construction(OLD)': 'CONSTRUCTION',
  'Construction & Operational': 'CONSTRUCTION',
  'CONSTRUCTION : Construction': 'CONSTRUCTION',
  'CONSTRUCTION : Construction & Operational': 'CONSTRUCTION',
  'CONSTRUCTION : Executive Project': 'CONSTRUCTION',
  'Executive Project': 'CONSTRUCTION',
  // preparation family — out of scope for CVS BU
  'PREPARATION': 'PREPARATION',
  'Pipeline': 'PREPARATION',
  'Scouting': 'PREPARATION',
  'Nominated': 'PREPARATION',
  'Preparation / RPF': 'PREPARATION',
  'Proposed / Executive Project Consip': 'PREPARATION',
  'PREPARATION : Nominated': 'PREPARATION',
  'PREPARATION : Preparation / RPF': 'PREPARATION',
  'PREPARATION : Proposed / Executive Project Consip': 'PREPARATION',
};

// Seller in CVS BU is either the literal "Organic" or, for comuni acquired through
// an M&A still in progress, the seller's name. The lookup is accent- and
// case-insensitive because the same comune is spelled inconsistently across sources
// ("Sant'arsenio" vs "Sant'Arsenio", "Fossò" vs "Fosso").
function organicKey(s) {
  return (s ?? '').toString().trim().toLowerCase()
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ').trim();
}

function lookupOrganic(comune, db) {
  if (!comune || !db.organicDB) return null;
  return db.organicDB[organicKey(comune)] || null;
}

// the family key used to test a code against the CVS BU whitelist
function activityCodeFamily(code) {
  if (code === null || code === undefined) return code;
  const s = code.toString().trim();
  return CVSBU_CODE_FAMILY[s] ?? s;
}

const AMOUNT_CATEGORIES = {
  '05 - Ricavi': 'ricavi',
  '03 - Manodopera': 'manodopera',
  '02 - Servizi': 'servizi',
  '04 - Materiali': 'materiali',
  '01 - Oneri': 'oneri',
};

function norm(s) {
  return (s ?? '').toString().trim().toLowerCase();
}

// Locate the header row and map each column index to its meaning.
function mapCommesseColumns(rows) {
  for (let i = 0; i < Math.min(rows.length, 20); i++) {
    const row = rows[i] || [];
    const cells = row.map(norm);
    const hasPid = cells.includes('project id');
    if (!hasPid) continue;

    const above = rows[i - 1] || [];
    const map = { headerRow: i, pid: -1, name: -1, act: -1, newact: -1, amounts: {} };
    for (let c = 0; c < row.length; c++) {
      const h = cells[c];
      if (h === 'project id') map.pid = c;
      else if (h === 'project name') map.name = c;
      else if (h === 'activity code' || h === 'activity code tr.' || h === 'activity code tr') map.act = c;
      else if (h.startsWith('new activity code')) map.newact = c;
      else if (h === 'importo') {
        const cat = AMOUNT_CATEGORIES[(above[c] ?? '').toString().trim()];
        if (cat) map.amounts[cat] = c;
      }
    }
    if (map.pid >= 0 && map.act >= 0 && map.amounts.ricavi !== undefined) return map;
  }
  return null;
}

function readCommesseRows(wb) {
  // prefer the enriched sheet when present, otherwise take the first sheet
  const sheetName = findSheet(wb, ['Elab 3']) || wb.SheetNames[0];
  const rows = sheetRows(wb, sheetName);
  const map = mapCommesseColumns(rows);
  if (!map) {
    return {
      error: `Nel foglio "${sheetName}" non trovo le intestazioni attese ` +
        `("Project ID", "Activity Code"/"Activity Code Tr.", "Importo" sotto "05 - Ricavi"). ` +
        `Fogli disponibili: ${wb.SheetNames.join(', ')}`,
    };
  }

  const isRaw = map.newact < 0; // the raw export has no manually-added NEW Activity Code
  const out = [];
  const unmappedLeaves = new Map();
  let pid = null, name = null;

  for (let i = map.headerRow + 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row) continue;

    // grouped layout: carry the project down its continuation rows
    const rawPid = row[map.pid];
    if (rawPid) { pid = rawPid; name = map.name >= 0 ? row[map.name] : null; }
    else if (!isRaw) { pid = null; }
    if (!pid) continue;

    const rawAct = row[map.act];
    if (rawAct === null || rawAct === undefined || rawAct === '') continue;

    const amt = (key) => {
      const c = map.amounts[key];
      if (c === undefined) return 0;
      const v = row[c];
      return typeof v === 'number' ? v : 0;
    };

    // the activity code is kept exactly as written in the source file
    const act = rawAct.toString().trim();
    if (!(act in CVSBU_CODE_FAMILY)) {
      const e = unmappedLeaves.get(act) || { rows: 0, ricavi: 0 };
      e.rows++; e.ricavi += amt('ricavi');
      unmappedLeaves.set(act, e);
    }

    out.push({
      pid, name: map.name >= 0 ? (row[map.name] ?? name) : name,
      act,
      newact: map.newact >= 0 ? row[map.newact] : null,
      ricavi: amt('ricavi'),
      dc: amt('manodopera') + amt('servizi') + amt('materiali') + amt('oneri'),
    });
  }

  return { records: out, isRaw, sheetName, unmappedLeaves };
}

// top-level codes that appear identically in both layouts
const CVSBU_KNOWN_TOP_CODES = new Set(['OPERATIONAL', 'PREPARATION', 'EXTRA LAVORI', 'CONSTRUCTION', 'GENERICO', '- No Activity Code -', 'NO ACTIVITY CODE']);

function processCVSBU(wb, db) {
  const parsed = readCommesseRows(wb);
  if (parsed.error) return { error: parsed.error };
  const { records, isRaw, sheetName, unmappedLeaves } = parsed;

  const whitelist = new Set(db.cvsBuWhitelist);
  const nonEpcComuni = new Set(db.nonEpcComuni);

  // group normalized records by project
  const byPid = {};
  for (const rec of records) {
    if (!byPid[rec.pid]) byPid[rec.pid] = [];
    byPid[rec.pid].push(rec);
  }

  const groups = {}; // (pid, code) -> {revenue, dc}
  const anomalies = [];

  // A code is in scope when its FAMILY is whitelisted, but rows are grouped and
  // written out under the code exactly as it appears in the source file — so a
  // renamed code (e.g. "Operation & Maintenance") shows up as its own row rather
  // than being merged into the family it belongs to.
  const inScope = (code) => code != null && whitelist.has(activityCodeFamily(code));

  for (const [pid, recs] of Object.entries(byPid)) {
    for (const rec of recs) {
      let code = null;
      if (inScope(rec.newact)) code = rec.newact;
      else if (inScope(rec.act)) code = rec.act;

      if (code) {
        const key = pid + '\u0001' + code;
        if (!groups[key]) groups[key] = { pid, code, revenue: 0, dc: 0 };
        groups[key].revenue += rec.ricavi;
        groups[key].dc += rec.dc;
      } else if (Math.abs(rec.ricavi) > 0.01) {
        // revenue sitting under an out-of-scope activity code -> real anomaly
        const proposals = new Set();
        for (const r2 of recs) {
          if (inScope(r2.act)) proposals.add(r2.act);
          if (inScope(r2.newact)) proposals.add(r2.newact);
        }
        anomalies.push({
          pid, actCode: rec.act, ricavi: rec.ricavi,
          proposals: [...proposals],
        });
      }
      // out-of-scope with zero revenue (pure construction/prep cost) -> belongs to CapEx
    }
  }

  // Resolve a project's descriptive fields. Shared by imported rows AND anomaly rows,
  // so an anomaly is never a row of dashes — it carries the same comune/BU/stream/seller
  // as any other row and only differs in why it is being flagged.
  function resolveProject(pid) {
    const hist = db.cvsBuProjectDB[pid];
    const recs = byPid[pid] || [];
    const rec = recs[0];
    const projectName = (db.projectNames && db.projectNames[pid]) || (rec && rec.name) || '';
    const notes = [];

    if (hist) {
      // the cadastral code is an independent check on the recorded BU: the DB commesse
      // still wins, but a mismatch is always reported — it usually means the BU was
      // typed by hand for a private customer and points at the wrong area
      const cadHist = lookupCadastral(pid, db);
      const mismatch = cadHist && cadHist.bu && hist.bu && cadHist.bu !== hist.bu;
      return {
        comune: hist.comune, bu: hist.bu, streamI: hist.streamI, streamII: hist.streamII,
        seller: hist.seller, projectName, isNew: false,
        buMismatch: !!mismatch,
        reason: mismatch
          ? `BU DA VERIFICARE: nel DB commesse è "${hist.bu}", ma il codice catastale ${cadHist.code} nel Project ID corrisponde a ${cadHist.comune} → "${cadHist.bu}". Valore tenuto: quello del DB commesse.`
          : null,
        matchNote: 'storico (progetto già noto)',
      };
    }

    const { first, second } = projectIdSegments(pid);
    const nameGuess = (rec && rec.name) ? rec.name.split(':')[0] : '';
    const comune = stripComuneDiPrefix(nameGuess);

    // Seller / organic classification from the Organic-vs-M&A database
    const org = lookupOrganic(comune, db);
    let seller;
    if (org && org.status === 'M&A ongoing' && org.seller) {
      seller = org.seller;
      notes.push(`inorganic: M&A in corso con ${org.seller} (da DB Organic/Inorganic)`);
    } else if (org) {
      seller = 'Organic';
      notes.push('organic (da DB Organic/Inorganic)');
    } else {
      seller = 'Organic';
      notes.push('impostato Organic in via predefinita: comune/cliente NON presente nel DB Organic/Inorganic — verificare la veridicità del seller');
    }

    // BU: the DB commesse is authoritative. When it doesn't know this name — the
    // usual case for a private customer — the cadastral code in the Project ID
    // gives the location, and only after that do the other sources get a turn.
    const cad = lookupCadastral(pid, db);
    let bu = db.comuneToBU[comune] || null;
    if (bu) {
      if (cad && cad.bu && cad.bu !== bu) {
        notes.push(`BU "${bu}" dal DB commesse (il codice catastale ${cad.code} = ${cad.comune} indicherebbe "${cad.bu}")`);
      }
    } else if (cad && cad.bu) {
      bu = cad.bu;
      notes.push(`BU dedotta dal codice catastale ${cad.code} (${cad.comune}) contenuto nel Project ID`);
    } else if (org && org.bu) {
      bu = org.bu;
      notes.push('BU dedotta dal DB Organic/Inorganic');
    } else if (cad && !cad.bu) {
      notes.push(`codice catastale "${cad.code}" non riconosciuto — BU da inserire a mano`);
    }
    if (bu && org && org.bu && org.bu !== bu && db.comuneToBU[comune]) {
      // already reported above
    } else if (bu && org && org.bu && org.bu !== bu) {
      notes.push(`il DB Organic/Inorganic riporta "${org.bu}"`);
    }

    let streamI, streamII;
    if (first === 'EPC') {
      const isKnownComune = nonEpcComuni.has(comune);
      streamI = isKnownComune ? 'Extra Revenues' : 'One Off Works';
      streamII = streamI;
      notes.push(`commessa EPC nuova — proposta "${streamI}" (${isKnownComune ? 'comune già attivo con altro codice' : 'nessun altro codice per questo comune/cliente'}), da confermare`);
    } else if (CVSBU_SEGMENT_MAP[second]) {
      streamI = CVSBU_SEGMENT_MAP[second];
      streamII = second === 'IPU' ? first : streamI;
      notes.push('progetto nuovo — verificare BU/classificazione');
    } else {
      streamI = '?'; streamII = '?';
      notes.push(`segmento "${second}" sconosciuto — classificazione manuale necessaria`);
    }

    return {
      comune, bu, streamI, streamII, seller, projectName, isNew: true,
      reason: notes.join(' · '),
      matchNote: 'nuovo progetto (nessuno storico)',
    };
  }

  const results = [];
  for (const g of Object.values(groups)) {
    const p = resolveProject(g.pid);
    results.push({
      key: nextKey(), status: (p.isNew || p.buMismatch) ? 'flag' : 'auto', reason: p.reason,
      fields: {
        seller: p.seller || '?', activityCode: g.code, projectName: p.projectName, projectId: g.pid,
        comune: p.comune || '?', chiave: '', bu: p.bu || '?',
        streamI: p.streamI || '?', streamII: p.streamII || '?',
        revenue: Math.round(g.revenue * 100) / 100, directCost: Math.round(g.dc * 100) / 100,
        stato: p.isNew ? 'da rivedere' : (p.buMismatch ? 'BU da verificare' : ''),
      },
      matchNote: p.matchNote,
    });
  }

  // Explain an out-of-scope code in business terms rather than as "not whitelisted".
  const FAMILY_REASON = {
    CONSTRUCTION: 'la commessa è in fase CONSTRUCTION (fase di costruzione: i costi vanno a CapEx, non dovrebbe generare ricavi in CVS BU)',
    PREPARATION: 'la commessa è in fase PREPARATION (fase preliminare: non dovrebbe ancora generare ricavi)',
  };

  // Only collapse when a single unrecognised code produces a wall of identical rows;
  // a handful of cases is more useful shown one by one, with each project named.
  const COLLAPSE_THRESHOLD = 15;
  const perCode = new Map();
  for (const a of anomalies) {
    const e = perCode.get(a.actCode) || { rows: 0, ricavi: 0, pids: [] };
    e.rows++; e.ricavi += a.ricavi;
    if (e.pids.length < 3) e.pids.push(a.pid);
    perCode.set(a.actCode, e);
  }
  const collapsed = new Set([...perCode.entries()].filter(([, e]) => e.rows > COLLAPSE_THRESHOLD).map(([c]) => c));

  // comuni that DO have an in-scope project, to suggest a likely correct project code
  const comuneToInScopePids = new Map();
  for (const g of Object.values(groups)) {
    const p = resolveProject(g.pid);
    if (!p.comune) continue;
    const k = organicKey(p.comune);
    if (!comuneToInScopePids.has(k)) comuneToInScopePids.set(k, new Set());
    comuneToInScopePids.get(k).add(g.pid);
  }

  for (const a of anomalies) {
    if (collapsed.has(a.actCode)) continue;
    const p = resolveProject(a.pid);
    const family = activityCodeFamily(a.actCode);
    const why = FAMILY_REASON[family] ||
      `l'Activity Code "${a.actCode}" non rientra fra quelli previsti per CVS BU`;

    const fixes = [];
    if (a.proposals.length) {
      fixes.push(`Activity Code corretto probabile: ${a.proposals.join(' / ')} (già presente sulla stessa commessa)`);
    }
    const siblings = [...(comuneToInScopePids.get(organicKey(p.comune)) || [])].filter(x => x !== a.pid);
    if (siblings.length) {
      fixes.push(`oppure i ricavi appartengono a un'altra commessa dello stesso comune: ${siblings.slice(0, 3).join(', ')}`);
    }
    if (!fixes.length) {
      fixes.push('nessun candidato automatico: riclassificare a mano');
    }

    results.push({
      key: nextKey(), status: 'anomaly',
      reason: `ANOMALIA: ricavi per ${fmtEUR(a.ricavi)} € ma ${why}. ${fixes.join(' — ')}.`,
      fields: {
        seller: p.seller || '?', activityCode: a.actCode, projectName: p.projectName, projectId: a.pid,
        comune: p.comune || '?', chiave: '', bu: p.bu || '?',
        streamI: p.streamI || '?', streamII: p.streamII || '?',
        revenue: a.ricavi, directCost: 0,
        stato: 'anomalia',
      },
      matchNote: p.matchNote,
    });
  }

  for (const code of collapsed) {
    const e = perCode.get(code);
    results.push({
      key: nextKey(), status: 'anomaly',
      reason: `ANOMALIA: Activity Code "${code}" non riconosciuto — ${e.rows} commesse con ricavi, ` +
        `totale ${fmtEUR(e.ricavi)} € (es. ${e.pids.join(', ')}). ` +
        `Va deciso se rientra in CVS BU e sotto quale codice: finché non lo si stabilisce non viene importato.`,
      fields: {
        seller: '?', activityCode: code, projectName: `${e.rows} commesse`, projectId: '—',
        comune: '?', chiave: '', bu: '?', streamI: '?', streamII: '?',
        revenue: e.ricavi, directCost: 0,
        stato: 'anomalia',
      },
      matchNote: 'riepilogo',
    });
  }

  return {
    results,
    columns: [
      { key: 'seller', label: 'Seller (J)' },
      { key: 'activityCode', label: 'Activity Code (K)' },
      { key: 'projectName', label: 'Project Name (L)' },
      { key: 'projectId', label: 'Project ID (M)' },
      { key: 'comune', label: 'Comune (N)' },
      { key: 'chiave', label: 'Chiave (O)' },
      { key: 'bu', label: 'BU (P)' },
      { key: 'streamI', label: 'Business Stream I (Q)' },
      { key: 'streamII', label: 'Business Stream II (R)' },
      { key: 'revenue', label: 'Revenues — mese corrente €', numeric: true },
      { key: 'directCost', label: 'Direct Costs — mese corrente €', numeric: true },
      // kept last on purpose: J:R stay contiguous for a straight paste into the sheet
      { key: 'stato', label: 'Stato' },
      { key: 'nota', label: 'Nota' },
    ],
    sheetName, isRaw,
  };
}

/* ============================================================================
   PERSISTENT SHARED DATABASE
   ============================================================================ */

function useDatabase() {
  const [db, setDb] = useState(SEED_DATA);
  const [loading, setLoading] = useState(true);
  const [source, setSource] = useState('seed');

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        // Each top-level table of SEED_DATA is stored as its own doc: the
        // shared "db" capability caps a single document at 256 KiB, and the
        // whole reconciliation DB serialized is well past that.
        const claudeDb = await window.claude?.use?.('db');
        if (!claudeDb) {
          setSource('locale (storage non disponibile)');
          return;
        }
        const snap = await claudeDb.collection('reconciliation').get();
        if (!cancelled && !snap.empty) {
          const loaded = {};
          for (const doc of snap.docs) loaded[doc.id] = doc.data().value;
          setDb({ ...SEED_DATA, ...loaded });
          setSource('condiviso');
        } else if (!cancelled) {
          await Promise.all(
            Object.entries(SEED_DATA).map(([key, value]) =>
              claudeDb.collection('reconciliation').doc(key).set({ value })
            )
          );
          setSource('seed (primo avvio)');
        }
      } catch (e) {
        setSource('locale (storage non disponibile)');
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  return { db, loading, source };
}

/* ============================================================================
   UI PRIMITIVES
   ============================================================================ */

function StatusPill({ status }) {
  const map = {
    auto: { icon: Check, label: 'auto', cls: 'pill-auto' },
    flag: { icon: AlertTriangle, label: 'da rivedere', cls: 'pill-flag' },
    anomaly: { icon: AlertOctagon, label: 'anomalia', cls: 'pill-anomaly' },
  };
  const m = map[status] || map.auto;
  const Icon = m.icon;
  return (
    <span className={`pill ${m.cls}`}>
      <Icon size={12} strokeWidth={2.5} />
      {m.label}
    </span>
  );
}

function UploadSlot({ label, hint, onFile, fileName, accept }) {
  const inputRef = useRef(null);
  const [dragOver, setDragOver] = useState(false);

  const handleFiles = (files) => {
    if (files && files[0]) onFile(files[0]);
  };

  return (
    <div
      className={`upload-slot ${dragOver ? 'drag-over' : ''} ${fileName ? 'has-file' : ''}`}
      onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
      onDragLeave={() => setDragOver(false)}
      onDrop={(e) => { e.preventDefault(); setDragOver(false); handleFiles(e.dataTransfer.files); }}
      onClick={() => inputRef.current?.click()}
    >
      <input
        ref={inputRef} type="file" accept={accept} style={{ display: 'none' }}
        onChange={(e) => handleFiles(e.target.files)}
      />
      {fileName ? (
        <>
          <FileSpreadsheet size={22} strokeWidth={1.6} />
          <div className="upload-filename">{fileName}</div>
          <div className="upload-swap">clicca per sostituire</div>
        </>
      ) : (
        <>
          <Upload size={22} strokeWidth={1.6} />
          <div className="upload-label">{label}</div>
          <div className="upload-hint">{hint}</div>
        </>
      )}
    </div>
  );
}

/* ============================================================================
   MAIN APP
   ============================================================================ */

export default function App() {
  const { db, loading: dbLoading, source: dbSource } = useDatabase();
  const [mode, setMode] = useState('capex');
  const [files, setFiles] = useState({});
  const [processing, setProcessing] = useState(false);
  const [output, setOutput] = useState(null);
  const [error, setError] = useState(null);
  const [filter, setFilter] = useState(null); // null | 'auto' | 'flag' | 'anomaly'

  const modeConfig = MODES.find(m => m.id === mode);

  useEffect(() => {
    setFiles({}); setOutput(null); setError(null); setFilter(null);
  }, [mode]);

  const setFile = (slot) => (file) => {
    setFiles(prev => ({ ...prev, [slot]: file }));
    setOutput(null); setError(null); setFilter(null);
  };

  const canProcess = useMemo(() => {
    if (mode === 'bdv') return files.tb && files.pl;
    return !!files.main;
  }, [mode, files]);

  const handleProcess = useCallback(async () => {
    setProcessing(true); setError(null); setOutput(null); setFilter(null);
    try {
      let result;
      if (mode === 'capex') {
        const wb = await readWorkbookFromFile(files.main);
        result = processCapEx(wb, db);
      } else if (mode === 'bdv') {
        const wbTB = await readWorkbookFromFile(files.tb);
        const wbPL = await readWorkbookFromFile(files.pl);
        const wbDG = files.dg ? await readWorkbookFromFile(files.dg) : null;
        result = processBDV(wbTB, wbPL, db, wbDG);
      } else if (mode === 'sgp') {
        const wb = await readWorkbookFromFile(files.main);
        result = processSGP(wb, db);
      } else if (mode === 'cvsbu') {
        const wb = await readWorkbookFromFile(files.main);
        result = processCVSBU(wb, db);
      }
      if (result.error) setError(result.error);
      else setOutput(result);
    } catch (e) {
      setError(`Errore durante l'elaborazione: ${e.message}`);
    } finally {
      setProcessing(false);
    }
  }, [mode, files, db]);

  const stats = useMemo(() => {
    if (!output) return null;
    const auto = output.results.filter(r => r.status === 'auto').length;
    const flag = output.results.filter(r => r.status === 'flag').length;
    const anomaly = output.results.filter(r => r.status === 'anomaly').length;
    return { auto, flag, anomaly, total: output.results.length };
  }, [output]);

  const toggleFilter = (status) => {
    setFilter(prev => prev === status ? null : status);
  };

  const visibleResults = useMemo(() => {
    if (!output) return [];
    return filter ? output.results.filter(r => r.status === filter) : output.results;
  }, [output, filter]);

  // export always includes every row, regardless of the on-screen filter —
  // the filter is a review aid, not a data selector, so nothing gets silently left out
  // Stato and Nota are review aids rather than source data: derive them from the row's
  // status and reason so every module gets them, without each module having to carry
  // the two extra fields on every row it builds.
  const STATO_LABEL = { auto: '', flag: 'da rivedere', anomaly: 'anomalia' };
  const cellValue = (r, key) => {
    if (key === 'stato') return r.fields.stato ?? STATO_LABEL[r.status] ?? '';
    if (key === 'nota') return r.reason || r.matchNote || '';
    return r.fields[key];
  };

  const handleExport = () => {
    if (!output) return;
    const columns = output.columns.map(c => ({
      label: c.label,
      get: (r) => c.numeric ? fmtEURExport(cellValue(r, c.key)) : (cellValue(r, c.key) ?? ''),
    }));
    const csv = toCSV(output.results, columns);
    downloadText(`${mode}_pulito_${new Date().toISOString().slice(0, 10)}.csv`, csv);
  };

  return (
    <div className="app-root">
      <style>{FONT_IMPORT}</style>
      <style>{STYLES}</style>

      <aside className="rail">
        <div className="rail-brand">
          <div className="rail-brand-mark">CS</div>
          <div>
            <div className="rail-brand-title">Riclassifica</div>
            <div className="rail-brand-sub">CiviSmart FP&amp;A</div>
          </div>
        </div>

        <nav className="rail-nav">
          {MODES.map(m => {
            const Icon = m.icon;
            const active = m.id === mode;
            return (
              <button key={m.id} className={`rail-item ${active ? 'active' : ''}`} onClick={() => setMode(m.id)}>
                <Icon size={17} strokeWidth={1.8} />
                <span>{m.label}</span>
                {active && <ChevronRight size={14} className="rail-item-chevron" />}
              </button>
            );
          })}
        </nav>

        <div className="rail-db">
          <div className="rail-db-head">
            <Database size={13} strokeWidth={2} />
            <span>Database {dbLoading ? '…' : dbSource}</span>
          </div>
          {!dbLoading && (
            <div className="rail-db-stats">
              <div><span>{Object.keys(db.comuneToBU).length}</span> comuni → BU</div>
              <div><span>{Object.keys(db.cvsBuProjectDB).length}</span> commesse note</div>
              <div><span>{Object.keys(db.sgpLegend).length}</span> voci SGP</div>
              <div><span>{Object.keys(db.bdvAccounts).length}</span> conti BDV</div>
            </div>
          )}
        </div>
      </aside>

      <main className="main">
        <header className="main-header">
          <div>
            <h1>{modeConfig.label}</h1>
            <p className="main-tagline">{modeConfig.tagline}</p>
          </div>
          <div className="main-dest">
            <span className="main-dest-label">destinazione</span>
            <span className="main-dest-value">{modeConfig.dest}</span>
          </div>
        </header>

        <section className="upload-section">
          {mode === 'bdv' ? (
            <div className="upload-grid upload-grid-3">
              <UploadSlot label="Bilancio di Verifica" hint="es. BDV_al_30_06.xls" accept={modeConfig.accept}
                onFile={setFile('tb')} fileName={files.tb?.name} />
              <UploadSlot label="Profit &amp; Loss per classe" hint="es. ProfitandLoss293.xls" accept={modeConfig.accept}
                onFile={setFile('pl')} fileName={files.pl?.name} />
              <UploadSlot label="Bilancio De Giorgi (facoltativo)" hint="il file di mappatura con il bridge dei conti" accept=".xlsx,.xls"
                onFile={setFile('dg')} fileName={files.dg?.name} />
            </div>
          ) : (
            <UploadSlot label={modeConfig.fileHint} hint="trascina qui o clicca per scegliere" accept={modeConfig.accept}
              onFile={setFile('main')} fileName={files.main?.name} />
          )}

          <button className="process-btn" disabled={!canProcess || processing} onClick={handleProcess}>
            {processing ? <Loader2 size={16} className="spin" /> : <RefreshCw size={16} />}
            {processing ? 'Elaborazione…' : 'Elabora'}
          </button>
        </section>

        {error && (
          <div className="error-box">
            <AlertOctagon size={16} />
            <span>{error}</span>
          </div>
        )}

        {output && stats && (
          <>
            <section className="summary-bar">
              <button
                className={`summary-stat auto ${filter === 'auto' ? 'is-active' : ''}`}
                onClick={() => toggleFilter('auto')} title="Filtra: solo auto-applicate"
              >
                <Check size={14} /> <span>{stats.auto}</span> auto-applicate
              </button>
              {stats.flag > 0 && (
                <button
                  className={`summary-stat flag ${filter === 'flag' ? 'is-active' : ''}`}
                  onClick={() => toggleFilter('flag')} title="Filtra: solo da rivedere"
                >
                  <AlertTriangle size={14} /> <span>{stats.flag}</span> da rivedere
                </button>
              )}
              {stats.anomaly > 0 && (
                <button
                  className={`summary-stat anomaly ${filter === 'anomaly' ? 'is-active' : ''}`}
                  onClick={() => toggleFilter('anomaly')} title="Filtra: solo anomalie"
                >
                  <AlertOctagon size={14} /> <span>{stats.anomaly}</span> anomalie
                </button>
              )}
              {filter && (
                <button className="filter-clear" onClick={() => setFilter(null)}>
                  <X size={12} /> mostra tutte
                </button>
              )}
              <div className="summary-spacer" />
              <button className="export-btn" onClick={handleExport}>
                <Download size={14} /> Esporta CSV
              </button>
            </section>

            <section className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th className="col-status">stato</th>
                    {output.columns.map(c => (
                      <th key={c.key} className={c.numeric ? 'col-numeric' : ''}>{c.label}</th>
                    ))}
                    <th>nota</th>
                  </tr>
                </thead>
                <tbody>
                  {visibleResults.map(r => (
                    <tr key={r.key} className={`row-${r.status}`}>
                      <td className="col-status"><StatusPill status={r.status} /></td>
                      {output.columns.map(c => (
                        <td key={c.key} className={c.numeric ? 'col-numeric mono' : 'mono'}>
                          {c.numeric ? fmtEUR(cellValue(r, c.key)) : (cellValue(r, c.key) ?? '')}
                        </td>
                      ))}
                      <td className="col-note">
                        {r.reason ? <span className="note-reason">{r.reason}</span> : (r.matchNote || '')}
                      </td>
                    </tr>
                  ))}
                  {visibleResults.length === 0 && (
                    <tr>
                      <td colSpan={output.columns.length + 2} className="empty-filter">
                        Nessuna riga in questa categoria.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </section>
          </>
        )}

        {!output && !error && (
          <div className="empty-state">
            <Info size={18} />
            <p>Carica {mode === 'bdv' ? 'i file grezzi (il bilancio De Giorgi è facoltativo: se lo aggiungi, l\'output riporta una colonna per CVS e una per De Giorgi)' : 'il file grezzo'} per iniziare. L'app applica le regole imparate insieme e segnala solo quello che ha davvero bisogno di una tua decisione.</p>
          </div>
        )}
      </main>
    </div>
  );
}

